>Início</dt><dd>{{\App\Web\Presentation::time($diagnostic->started_at,'H:i:s')??'Aguardando'}}</dd></div><div><dt>Conclusão</dt><dd>{{\App\Web\Presentation::time($diagnostic->finished_at,'H:i:s')??'Em andamento'}}</dd></div></dl></section>@if(!$terminal)@can('cancel',$diagnostic)<section class="card"><h2>Interromper investigação</h2><p class="muted" style="font-size:12px">As evidências coletadas serão mantidas.</p><form method="post" action="{{route('diagnostics.cancel',$diagnostic)}}" data-confirm="Cancelar este diagnóstico? A execução será interrompida e as evidências já coletadas serão preservadas.">@csrf<button class="button-secondary">Cancelar diagnóstico</button></form></section>@endcan @endif</aside></div>

